    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        --page-bg: #090d16;
        --panel-bg: #111827;
        --panel-border: #334155;
        --text: #f8fafc;
        --muted: #cbd5e1;
        --field-bg: #0f172a;
        --field-border: #64748b;
        --field-border-hover: #94a3b8;
        --accent: #38bdf8;
        --accent-strong: #0ea5e9;
        --error: #fca5a5;
        --error-border: #f87171;
        --success: #86efac;
      }

      * {
        box-sizing: border-box;
      }

      html {
        min-width: 320px;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #172554 0, transparent 34rem),
          radial-gradient(circle at bottom right, #0f766e 0, transparent 28rem),
          var(--page-bg);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        padding: 0.7rem 1rem;
        color: #03121e;
        background: var(--accent);
        border-radius: 999px;
        transform: translateY(-200%);
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #f8fafc;
      }

      .page-shell {
        width: min(100% - 2rem, 70rem);
        margin: 0 auto;
        padding: 3rem 0;
      }

      header {
        margin-bottom: 2rem;
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--accent);
        font-size: 0.9rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        max-width: 14ch;
        margin: 0;
        font-size: clamp(2.25rem, 8vw, 5rem);
        line-height: 0.95;
        letter-spacing: -0.06em;
      }

      .intro {
        max-width: 42rem;
        margin: 1rem 0 0;
        color: var(--muted);
        font-size: 1.1rem;
      }

      main {
        display: grid;
        gap: 1.5rem;
        align-items: start;
        grid-template-columns: minmax(0, 1fr);
      }

      .support-card,
      .contact-form {
        border: 1px solid var(--panel-border);
        border-radius: 1.5rem;
        background: linear-gradient(145deg, #111827 0%, #0f172a 100%);
        box-shadow: 0 1.5rem 4rem #00000099;
      }

      .support-card {
        padding: 1.25rem;
        color: var(--muted);
      }

      .support-card h2 {
        margin: 0 0 0.5rem;
        color: var(--text);
        font-size: 1.25rem;
      }

      .support-card p {
        margin: 0;
      }

      .contact-form {
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .form-field {
        margin-bottom: 1.25rem;
      }

      label {
        display: block;
        margin-bottom: 0.45rem;
        font-weight: 700;
      }

      .required-note,
      .required-mark {
        color: var(--muted);
        font-weight: 600;
      }

      .required-mark {
        margin-left: 0.2rem;
      }

      input {
        display: block;
        width: 100%;
        min-height: 3.15rem;
        padding: 0.75rem 0.9rem;
        color: var(--text);
        background: var(--field-bg);
        border: 1px solid var(--field-border);
        border-radius: 0.9rem;
        font: inherit;
        outline: 3px solid transparent;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease,
          background-color 160ms ease;
      }

      input:hover {
        border-color: var(--field-border-hover);
      }

      input:focus {
        border-color: var(--accent);
        box-shadow: 0 0 0 4px #38bdf84d;
      }

      input[aria-invalid="true"] {
        border-color: var(--error-border);
      }

      input[aria-invalid="true"]:focus {
        box-shadow: 0 0 0 4px #f871714d;
      }

      .helper-text,
      .error-message {
        margin: 0.4rem 0 0;
        font-size: 0.95rem;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-message {
        display: none;
        color: var(--error);
        font-weight: 700;
      }

      .error-message:not(:empty) {
        display: block;
      }

      .form-actions {
        margin-top: 1.5rem;
      }

      button {
        width: 100%;
        min-height: 3.25rem;
        padding: 0.85rem 1.2rem;
        color: #02131f;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        border: 0;
        border-radius: 999px;
        font: inherit;
        font-weight: 900;
        cursor: pointer;
        outline: 3px solid transparent;
        transition:
          transform 160ms ease,
          box-shadow 160ms ease,
          filter 160ms ease;
      }

      button:hover {
        filter: brightness(1.08);
        transform: translateY(-1px);
      }

      button:focus {
        box-shadow:
          0 0 0 4px var(--page-bg),
          0 0 0 7px var(--accent);
      }

      button:active {
        transform: translateY(0);
      }

      .form-status {
        min-height: 1.5rem;
        margin: 1rem 0 0;
        color: var(--success);
        font-weight: 700;
      }

      footer {
        margin-top: 2rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      @media (min-width: 48rem) {
        main {
          grid-template-columns: minmax(14rem, 0.75fr) minmax(24rem, 1fr);
        }

        .support-card {
          position: sticky;
          top: 1rem;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        body,
        .support-card,
        .contact-form,
        input {
          color: CanvasText;
          background: Canvas;
        }

        .support-card,
        .contact-form,
        input,
        button {
          border: 1px solid ButtonBorder;
        }

        .eyebrow,
        .helper-text,
        .required-note,
        .required-mark,
        footer,
        .support-card {
          color: CanvasText;
        }

        .error-message {
          color: Mark;
        }

        .form-status {
          color: CanvasText;
        }

        button,
        .skip-link {
          color: ButtonText;
          background: ButtonFace;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div class="page-shell">
      <header>
        <p class="eyebrow">Support</p>
        <h1>Contact our team</h1>
        <p class="intro">
          Tell us how to reach you and a support specialist will follow up with
          the next steps.
        </p>
      </header>

      <main id="main-content">
        <section class="support-card" aria-labelledby="support-heading">
          <h2 id="support-heading">What happens next?</h2>
          <p>
            We review every request and prioritize urgent support needs. Required
            fields are marked with an asterisk.
          </p>
        </section>

        <div id="app"></div>
      </main>

      <footer>
        <p>Response times may vary during weekends and holidays.</p>
      </footer>
    </div>

    <script>
      const fields = [
        {
          id: "full-name",
          name: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          validate(value) {
            return value.trim() ? "" : "Enter your full name.";
          },
        },
        {
          id: "email",
          name: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          validate(value) {
            const trimmedValue = value.trim();
            const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

            if (!trimmedValue) {
              return "Enter your email address.";
            }

            return emailPattern.test(trimmedValue)
              ? ""
              : "Enter an email address in the format name@example.com.";
          },
        },
        {
          id: "phone",
          name: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          helperText: "Optional. Use 10 digits, such as 555-123-4567.",
          validate(value) {
            const trimmedValue = value.trim();
            const phonePattern =
              /^(?:\+?1[\s.-]?)?(?:\(?[2-9]\d{2}\)?[\s.-]?)?[2-9]\d{2}[\s.-]?\d{4}$/;

            if (!trimmedValue) {
              return "";
            }

            return phonePattern.test(trimmedValue)
              ? ""
              : "Enter a phone number like 555-123-4567, or leave it blank.";
          },
        },
      ];

      function createElement(tagName, attributes = {}, children = []) {
        const element = document.createElement(tagName);

        Object.entries(attributes).forEach(([key, value]) => {
          if (value === false || value === null || value === undefined) {
            return;
          }

          if (key === "className") {
            element.className = value;
          } else if (key === "textContent") {
            element.textContent = value;
          } else if (key === "required" && value === true) {
            element.required = true;
          } else {
            element.setAttribute(key, value);
          }
        });

        children.forEach((child) => element.append(child));
        return element;
      }

      function FormField(field, formState) {
        const helperId = `${field.id}-helper`;
        const errorId = `${field.id}-error`;
        const describedBy = [field.helperText ? helperId : null, errorId]
          .filter(Boolean)
          .join(" ");

        const label = createElement("label", { for: field.id });
        label.append(field.label);

        if (field.required) {
          label.append(
            createElement("span", {
              className: "required-mark",
              textContent: "*",
              "aria-hidden": "true",
            })
          );
          label.append(
            createElement("span", {
              className: "required-note",
              textContent: " required",
            })
          );
        } else {
          label.append(
            createElement("span", {
              className: "required-note",
              textContent: " optional",
            })
          );
        }

        const input = createElement("input", {
          id: field.id,
          name: field.name,
          type: field.type,
          autocomplete: field.autocomplete,
          required: field.required,
          "aria-describedby": describedBy,
          "aria-invalid": "false",
        });

        const error = createElement("p", {
          id: errorId,
          className: "error-message",
        });

        input.addEventListener("blur", () => formState.validateField(field));
        input.addEventListener("input", () => {
          if (input.getAttribute("aria-invalid") === "true") {
            formState.validateField(field);
          }
        });

        const children = [label, input];

        if (field.helperText) {
          children.push(
            createElement("p", {
              id: helperId,
              className: "helper-text",
              textContent: field.helperText,
            })
          );
        }

        children.push(error);
        return createElement("div", { className: "form-field" }, children);
      }

      function ContactForm() {
        const status = createElement("p", {
          className: "form-status",
          "aria-live": "polite",
        });

        const formState = {
          validateField(field) {
            const input = document.getElementById(field.id);
            const error = document.getElementById(`${field.id}-error`);
            const message = field.validate(input.value);

            input.setAttribute("aria-invalid", message ? "true" : "false");
            error.textContent = message;
            return !message;
          },
        };

        const form = createElement(
          "form",
          {
            className: "contact-form",
            action: "#",
            method: "post",
            novalidate: "novalidate",
          },
          [
            ...fields.map((field) => FormField(field, formState)),
            createElement("div", { className: "form-actions" }, [
              createElement("button", { type: "submit", textContent: "Submit support request" }),
            ]),
            status,
          ]
        );

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          status.textContent = "";

          const firstInvalidField = fields.find(
            (field) => !formState.validateField(field)
          );

          if (firstInvalidField) {
            document.getElementById(firstInvalidField.id).focus();
            return;
          }

          form.reset();
          fields.forEach((field) => formState.validateField(field));
          status.textContent = "Thanks. Your support request is ready to send.";
        });

        return form;
      }

      function App() {
        return ContactForm();
      }

      document.getElementById("app").append(App());
    </script>
  </body>
</html>
